const slides=[],groups=[];function registerGroup(key,label,start){const count=slides.length-start;if(!count)return;groups.push({key,label,start,count})}function addGroup(key,label,build){const start=slides.length;build();registerGroup(key,label,start)}
function addSlide(group,label,contextTitle,contextParts,makeTask){const slide=document.createElement('article');slide.className='slide';slide.hidden=true;slide.dataset.group=group;const left=document.createElement('section');left.className='context';left.append(el('div',group.startsWith('news-')?'NEWS · LISTEN & SAY':group.startsWith('listening')?'LISTEN CLOSELY':group.startsWith('reading')?'READ & DISCOVER':group.startsWith('grammar')?'GRAMMAR TOOLBOX':group==='speaking'?"LET’S TALK":'WORD EXPLORER','context-kicker'),el('h2',contextTitle));const body=document.createElement('div');body.className='context-body';for(const part of contextParts){if(part.type==='text')body.append(el('p',part.text,part.className||''));else if(part.type==='translation')body.append(translationDisclosure(part.text));else if(part.type==='block'){const b=el('div',undefined,'context-block');if(part.title)b.append(el('strong',part.title));b.append(el('span',part.text));body.append(b)}else if(part.type==='profiles'){const box=el('div',undefined,'profiles');for(const profile of part.items){const b=el('div',undefined,'context-block');b.append(el('strong',profile.label),el('span',profile.text));box.append(b)}body.append(box)}else if(part.type==='audio'){body.append(el('div',part.label,'audio-hint'));const audio=document.createElement('audio');audio.controls=true;audio.preload='metadata';audio.src=audioSource(part.src);audio.setAttribute('aria-label',part.aria||'Course recording');body.append(audio)}else if(part.type==='htmltext'){const p=el('p',part.text,'context-instructions');body.append(p)}}left.append(body);
const right=document.createElement('section');right.className='task';const head=el('div',undefined,'task-head');head.append(el('span',label,'task-kicker'),el('span','', 'question-index'));right.append(head);const content=el('div',undefined,'task-content');makeTask(content);right.append(content);slide.append(left,right);id('deck').append(slide);slides.push(slide)}
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function translationDisclosure(text){
 const box=el('div',undefined,'translation-disclosure'),button=el('button','显示中文','translation-toggle'),translation=el('p',text,'context-cn');
 translation.id=`vocab-translation-${slides.length}`;translation.hidden=true;translation.setAttribute('lang','zh-CN');
 button.type='button';button.setAttribute('lang','zh-CN');button.setAttribute('aria-controls',translation.id);button.setAttribute('aria-expanded','false');
 button.onclick=()=>{translation.hidden=!translation.hidden;button.textContent=translation.hidden?'显示中文':'隐藏中文';button.setAttribute('aria-expanded',String(!translation.hidden))};
 box.append(button,translation);return box;
}
function audioSource(src){const revision=COURSE.audio_revisions?.[src];return revision?`${src}?v=${revision.slice(0,12)}`:src}
function questionCard(item,answer,ctx){const q=el('div',undefined,'question-card');q.append(el('div',item.prompt,'qhead'));let inputs=[];if(Array.isArray(item.choices)){const opts=el('div',undefined,'options'),radioName=`q-${slides.length}-${Math.random()}`;item.choices.forEach((sourceChoice,i)=>{const choice=String.fromCharCode(65+i)+'. '+sourceChoice.replace(/^(?:[A-Z]\.\s*)+/,'');const label=el('label',undefined,'choice-row'),radio=document.createElement('input');radio.type='radio';radio.name=radioName;radio.value=(choice.match(/^([A-Z])\./)||[])[1]||choice;label.append(radio,el('span',choice));opts.append(label);inputs.push(radio);radio.onchange=()=>{if(radio.checked)check.onclick()}});q.append(opts)}else{const input=document.createElement('input');input.type='text';input.autocomplete='off';input.placeholder='Type your answer';input.className='answer-input';inputs.push(input);q.append(input)}
const feedback=el('p','','feedback');feedback.setAttribute('aria-live','polite');const answerBox=el('div',`Answer: ${answer}`,'answer'),explanation=el('div',[item.explanation,item.explanation_zh,item.evidence?'Evidence: '+item.evidence:''].filter(Boolean).join('\n'),'explanation');const actions=el('div',undefined,'question-actions');const check=el('button','Check answer','primary');check.type='button';check.onclick=()=>{const selected=inputs.find(x=>x.type==='radio'&&x.checked),typed=inputs.find(x=>x.type==='text'),response=selected?selected.value:(typed?.value||'').trim();if(!response){feedback.textContent='Choose or type an answer first.';feedback.className='feedback';return}const expected=selected?(item.answer||''):(item.answer||answer);const numberWords={one:'1',two:'2',three:'3',four:'4',five:'5',six:'6',seven:'7',eight:'8',nine:'9',ten:'10',eleven:'11',twelve:'12',sixteen:'16',twenty:'20'};const normalize=v=>String(v).trim().toLocaleLowerCase();const wanted=normalize(expected);const acceptable=[wanted,...(item.accepted_answers||[]).map(normalize),...(typed&&numberWords[wanted]?[numberWords[wanted]]:[])];const correct=acceptable.includes(normalize(response));feedback.textContent=correct?'Correct! Well done.':'Not quite. Check the shared context and try again.';feedback.className=correct?'feedback correct':'feedback retry'};const reveal=el('button','Show answer');reveal.type='button';reveal.onclick=()=>{answerBox.classList.toggle('show');reveal.textContent=answerBox.classList.contains('show')?'Hide answer':'Show answer'};const why=el('button','Why?');why.type='button';why.onclick=()=>{explanation.classList.toggle('show');why.textContent=explanation.classList.contains('show')?'Hide explanation':'Why?'};actions.append(check,reveal,why);q.append(feedback,actions,answerBox,explanation);return q}
function questionGroup(group,label,instructions,contextTitle,contextParts,questions,answers){addGroup(group,label,()=>questions.forEach((item,i)=>addSlide(group,label,contextTitle,contextParts,box=>{const idx=box.parentElement?.querySelector?.('.question-index');if(idx)idx.textContent=`Question ${i+1} of ${questions.length}`;box.append(questionCard(item,answers[i],group))})));}
function addQuestionSlides(group,label,instructions,contextTitle,contextParts,questions,answers){const start=slides.length;questions.forEach((item,i)=>addSlide(group,label,contextTitle,contextParts,box=>{box.append(el('div',`${i+1} / ${questions.length}`,'question-index'));box.append(questionCard(item,answers[i],group))}));if(slides.length>start)groups.push({key:group,label,start,count:slides.length-start})}
function contextText(instructions,text){return[{type:'text',text:instructions,className:'context-instructions'},{type:'text',text}]}function audioContext(instructions,text,path,label){const c=[{type:'text',text:instructions,className:'context-instructions'}];if(text)c.push({type:'text',text});c.push({type:'audio',src:path,label:label||'Listen to the recording. You may replay it.',aria:'Shared recording for this question set'});return c}
function appendQuestions(group,label,instructions,contextTitle,contextParts,questions,answers){const start=slides.length;questions.forEach((item,i)=>addSlide(group,label,contextTitle,contextParts,box=>{box.append(el('div',`Question ${i+1} of ${questions.length}`,'question-index'));box.append(questionCard(item,answers[i],group))}));registerGroup(group,label,start)}

