const rd=D.readings;const readParts=[['part1','Reading Part 1',D.answers.reading_part1],['part2','Reading Part 2',D.answers.reading_part2],['part3','Reading Part 3',D.answers.reading_part3],['part4','Reading Part 4',D.answers.reading_part4],['part5','Reading Part 5',D.answers.reading_part5]];
for(const [key,label,answers] of readParts){const p=rd[key];if(!p)continue;const sharedAudio={type:'audio',src:(D.audio?.[key]||`../../audio/day${String(D.day).padStart(2,'0')}/${key}.mp3`).replace('../../','../'),label:key==='part4'||key==='part5'?'Listen after you try. You may replay the recording.':'Read and listen. You may replay the recording.',aria:`${label} shared audio`};
if(key==='part1'){const start=slides.length;p.questions.forEach((q,i)=>{const tx=p.texts[i],text=typeof tx==='string'?tx:(tx.text||tx.notice||JSON.stringify(tx));const title=typeof tx==='string'?`Notice ${i+1}`:(tx.label||`Text ${i+1}`);addSlide(`reading-${key}`,label,title,[{type:'text',text},{type:'text',text:p.instructions,className:'context-instructions'},sharedAudio],box=>{box.append(el('div',`Question ${i+1} of ${p.questions.length}`,'question-index'));box.append(questionCard(q,answers[i],`reading-${key}`))})});registerGroup(`reading-${key}`,label,start)}
else{let c=[];if(p.texts)c.push({type:'profiles',items:p.texts.map((x,i)=>({label:x.label||String.fromCharCode(65+i),text:typeof x==='string'?x:(x.text||x.notice||JSON.stringify(x))}))});if(p.text)c.push({type:'text',text:p.text});c.push(sharedAudio);appendQuestions(`reading-${key}`,label,p.instructions,`${label} · shared text`,c,p.questions,answers)}}
